 "content": "from collections import Counter


def transform(grid):
    """Overlay the marked cells from the two panels around the solid divider."""
    h, w = len(grid), len(grid[0])
    divider = next(
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
        and c > 0 and c < w - 1
    )
    left, right = [row[:divider] for row in grid], [row[divider + 1:] for row in grid]
    n = min(len(left[0]), len(right[0]))
    left_bg = Counter(x for row in left for x in row).most_common(1)[0][0]
    right_bg = Counter(x for row in right for x in row).most_common(1)[0][0]
    return [
        [2 if left[r][c] != left_bg or right[r][c] != right_bg else 3 for c in range(n)]
        for r in range(h)
    ]
