 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = [c for c in range(1, w - 1)
                  if all(grid[r][c] == grid[0][c] for r in range(h))]
    sep = min(separators, key=lambda c: abs(c - (w - 1) / 2))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    n = min(len(left[0]), len(right[0]))

    def bg_fg(panel):
        counts = Counter(v for row in panel for v in row)
        ordered = counts.most_common()
        return ordered[0][0], (ordered[1][0] if len(ordered) > 1 else ordered[0][0])

    lb, lf = bg_fg(left)
    rb, rf = bg_fg(right)
    out = []
    for r in range(h):
        row = []
        for c in range(n):
            a, b = left[r][c], right[r][c]
            if lb == rb:
                # Shared backgrounds: show either panel's foreground feature.
                row.append(2 if (a != lb or b != rb) else 3)
            elif lf == rb:
                # Left feature is the right panel's background; right features cut it out.
                row.append(3 if (a == lf and b == rb) else lf)
            elif lb == rf:
                # Right feature is the left panel's background.
                row.append(3 if (a == lb and b == rf) else lb)
            elif lf == rf:
                # Shared foreground: show aligned feature intersections.
                row.append(3 if (a == lf and b == rf) else lf)
            else:
                row.append(2 if (a != lb or b != rb) else 3)
        out.append(row)
    return out
